import{z as B,x as l,o as e,c as n,q as t,j as r,D as E,d as i,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"隔离级别的实现","description":"","frontmatter":{"title":"隔离级别的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dt-isolation-implementation.md","filePath":"cs/dt-isolation-implementation.md","lastUpdated":1791063341000}'),C={name:"cs/dt-isolation-implementation.md"};function p(d,a,m,c,S,F){const A=l("Mermaid");return e(),n("div",null,[a[2]||(a[2]=t('<h1 id="隔离级别的实现" tabindex="-1">隔离级别的实现 <a class="header-anchor" href="#隔离级别的实现" aria-label="Permalink to &quot;隔离级别的实现&quot;">​</a></h1><div class="epigraph"><p>分布式下没有「默认可串行」：隔离等于全局可比的时间戳，加上提交点上的集中校验；缺一样，级别表就只是文档。</p><footer>—— 据 Berenson et al., A Critique of ANSI SQL Isolation Levels, SIGMOD 1995；Cahill et al., Serializable Isolation for Snapshot Databases, SIGMOD 2008 整理</footer></div><p><a href="/cs/dt-newsql-family">上一课</a>把谱系折算成时间戳来源。本课钉最后一块机制：同一张异常表（<a href="/cs/isolation-levels">隔离级别</a>），在单机 MVCC 上是一条可见性函数，跨片之后变成两件事——全局可比的戳，与提交点上的集中校验。主干课的 <a href="/cs/snapshot-isolation">快照隔离</a> 给过 startTS 与 commitTS 的单机版；本课补分片之后多出来的账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单机 SI 里，startTS 与 commitTS 由同一个引擎发号，天然可比。分片之后戳各片自报，「更早」失去定义：A 片上的读可能看不到 B 片上更早提交的写——不是可见性函数错了，是「更早」没定义。缺口有二。其一是<strong>全局可比的时间戳</strong>，上一课谱系里的四条路线就是为它而造。其二是<strong>提交点校验</strong>：写写冲突、以及可串行所需的更高档检查，必须在一个原子时刻集中判定。只做前者不做后者，得到的是「每个分片各自 SI」拼起来的系统：每片单独看都守级别，跨片读一遍就出异常，文档上写什么档都挡不住。</p><p><span class="marginnote">startTS／commitTS 可以直译成「开工戳／收工戳」：开工时取一个戳决定你能看见哪些版本，收工时再取一个决定你的写入对谁可见。单机里两个戳出自同一个发号器，比大小永不误会；分片后各片自己发号，两个「10:05」可能根本不可比——这正是全局可比戳要专门造一遍的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>账分三段。读路径：按 startTS 取全局快照，<a href="/cs/mvcc">MVCC</a> 的可见性函数原样可用，读不取锁；戳的分发方式（TSO、HLC、TrueTime）决定快照能新鲜到什么程度。写路径：悲观引擎写时取锁（锁在组长内存或数据表里），乐观引擎缓冲写集；<a href="/cs/gap-locks-predicate">间隙锁与谓词锁</a> 的范围问题在分片上更疼——范围跨片时谓词要拆成各片的键区间，无索引则退化成粗锁再叠网络。提交路径：2PC 的 prepare 阶段兼任校验点——锁在此刻集中，写写冲突在此刻定胜负（第一提交者胜）；这是跨片 2PC 在「原子结局」之外的第二职责，第一课的日志序在这里被复用成校验的串行化点。写偏斜要再高一档：SSI 在单机上靠追踪 rw 反依赖的危险结构（Cahill 等的算法），分布式下这个图跨节点，要么把判定搬进提交点，要么像 Calvin 那样用日志序直接免除——依赖环在定序时就没有机会形成。</p><p><span class="marginnote">SSI 的危险结构检测在单机是内存里的图（Postgres 的实现即如此）；跨片后这个图要跟着 prepare 一起在提交点对账——这也是 Postgres 的 SSI 走不出单机的结构性原因之一，不是没人想移植。</span></p><p><span class="marginnote">初学者容易以为「每片都开可串行化」合起来就是可串行化。实际上各片只在本地定序，跨片的读写交错在谁那里都没被检查；正文说的「提交点集中校验」就是把判定搬到一个所有分片都路过的原子时刻——没有这个时刻，级别表只对单片查询成立。</span></p>',10)),(e(),r(s,null,{default:E(()=>[o(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%80%BC%E7%8F%AD%E5%8C%BB%E7%94%9F%20Alice%20%E6%9F%A5%EF%BC%9A%E6%9C%89%E4%BA%BA%E5%9C%A8%E5%80%BC%E7%8F%AD%E5%90%97%EF%BC%9F%22%5D%20--%3E%20AR%5B%22%E5%BF%AB%E7%85%A7%E7%AD%94%EF%BC%9ABob%20%E5%9C%A8%22%5D%0A%20%20B%5B%22%E5%80%BC%E7%8F%AD%E5%8C%BB%E7%94%9F%20Bob%20%E6%9F%A5%EF%BC%9A%E6%9C%89%E4%BA%BA%E5%9C%A8%E5%80%BC%E7%8F%AD%E5%90%97%EF%BC%9F%22%5D%20--%3E%20BR%5B%22%E5%BF%AB%E7%85%A7%E7%AD%94%EF%BC%9AAlice%20%E5%9C%A8%22%5D%0A%20%20AR%20--%3E%20AW%5B%22Alice%20%E5%86%99%E8%87%AA%E5%B7%B1%E7%9A%84%E8%A1%8C%EF%BC%9A%E7%94%B3%E8%AF%B7%E4%BC%91%E5%81%87%22%5D%0A%20%20BR%20--%3E%20BW%5B%22Bob%20%E5%86%99%E8%87%AA%E5%B7%B1%E7%9A%84%E8%A1%8C%EF%BC%9A%E7%94%B3%E8%AF%B7%E4%BC%91%E5%81%87%22%5D%0A%20%20AW%20--%3E%20OK%5B%22%E4%B8%A4%E6%AC%A1%E5%86%99%E4%B8%8D%E5%90%8C%E8%A1%8C%EF%BC%8C%E5%86%99%E5%86%99%E5%86%B2%E7%AA%81%E6%A0%A1%E9%AA%8C%E6%94%BE%E8%A1%8C%22%5D%0A%20%20BW%20--%3E%20OK%0A%20%20OK%20--%3E%20BAD%5B%22%E7%BB%93%E6%9E%9C%EF%BC%9A%E6%B2%A1%E4%BA%BA%E5%80%BC%E7%8F%AD%E2%80%94%E2%80%94%E8%BF%99%E5%B0%B1%E6%98%AF%E5%86%99%E5%81%8F%E6%96%9C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把级别折算成实现动作，口径就硬了。读已提交：每语句取一次快照戳。可重复读与 SI：事务级快照加提交点写写校验。可串行：三条实现路——严格 2PL 加分布式死锁处理（<a href="/cs/distributed-deadlock">分布式死锁</a> 课的账）、分布式 SSI 加跨节点反依赖判定、确定性定序。外部一致（严格可串行）再加一条：提交序与真实时间序一致，那是 commit wait 买来的（<a href="/cs/spanner-truetime">Spanner 与 TrueTime</a>）。每个动作都有价：快照新鲜度受戳分发延迟限制，follower 读与 stale read 是拿旧快照换延迟的显式旋钮；旋钮拧过头，应用会看不到自己刚写的数据，会话一致性要靠会话戳自己保（<a href="/cs/replication-lag-rmw">复制延迟与读己之写</a> 的口径）。版本回收也多了跨片一问：老快照被长事务钉住时，GC 要全局协调谁还握着最老的戳（<a href="/cs/mvcc-gc">MVCC 版本回收</a> 的单机账在此加这一问）。</p><p><span class="marginnote">commit wait 可以类比寄挂号信：提交时取的是 TrueTime 区间的最晚可能值，系统宁可等掉一小段不确定窗（Spanner 上通常约 7 毫秒），保证任何后来发起的事务取快照时一定能看见你。这段等待买的不是速度，是「提交序 = 真实时间序」这行承诺。</span></p>',3)),(e(),r(s,null,{default:E(()=>[o(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TS%5B%22%E5%85%A8%E5%B1%80%E5%8F%AF%E6%AF%94%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%20--%3E%20SNAP%5B%22%E8%AF%BB%EF%BC%9A%E6%8C%89%20startTS%20%E5%8F%96%E5%85%A8%E5%B1%80%E5%BF%AB%E7%85%A7%22%5D%0A%20%20SNAP%20--%3E%20WB%5B%22%E5%86%99%EF%BC%9A%E5%8F%96%E9%94%81%E6%88%96%E7%BC%93%E5%86%B2%E5%86%99%E9%9B%86%22%5D%0A%20%20WB%20--%3E%20PR%5B%222PC%20prepare%EF%BC%9A%E9%9B%86%E4%B8%AD%E6%A0%A1%E9%AA%8C%E5%86%99%E5%86%99%E5%86%B2%E7%AA%81%22%5D%0A%20%20PR%20--%3E%20Q%7B%22%E8%A6%81%E5%8F%AF%E4%B8%B2%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20SER%5B%22%E4%B8%A5%E6%A0%BC%202PL%20%2F%20%E5%88%86%E5%B8%83%E5%BC%8F%20SSI%20%2F%20%E7%A1%AE%E5%AE%9A%E6%80%A7%E5%AE%9A%E5%BA%8F%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20SI%5B%22SI%EF%BC%9A%E5%86%99%E5%81%8F%E6%96%9C%E6%94%BE%E8%A1%8C%22%5D%0A%20%20TS%20--%3E%20EXT%5B%22commit%20wait%EF%BC%9A%E5%A4%96%E9%83%A8%E4%B8%80%E8%87%B4%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算各实现的性能公式，不重讲单机可见性函数，也不把因果一致性、并行快照划进级别表——那是不要求全序的另一档合同。判据始终是主干那条：先问允许哪些异常，再问校验动作发生在哪个原子时刻；两个答案都对上了，级别名才是可执行的承诺，否则只是厂商的默认值。下一课收束：把六课的协议与体系拼成选型与运维的清单。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分布式隔离 = 全局可比时间戳 + 提交点集中校验；缺一就只是分片级 SI 的拼盘。</li><li>prepare 阶段兼任校验点：写写冲突在此定胜负，这是跨片 2PC 的第二职责。</li><li>可串行三条路：分布式 2PL、分布式 SSI、确定性定序；外部一致再加 commit wait。</li><li>快照新鲜度是显式旋钮：stale read 与 follower 读换延迟，读己之写靠会话戳。</li><li>出处：Berenson et al. 1995；Cahill et al. 2008；Corbett et al. 2012。</li></ul>',4))])}const _=B(C,[["render",p]]);export{T as __pageData,_ as default};
